solution:
fn ask_question(question: Str, correct: Str, answer: Str) -> Bool {
  if answer == correct {
    return true;
  } else {
    return false;
  }
}

fn main() -> Int {
  var points = 0;
  if ask_question("Capital of France?", "Paris", "Paris") {
    points = points + 1;
  }
  if ask_question("5 * 6 = ?", "30", "30") {
    points = points + 1;
  }
  if ask_question("Earth is flat?", "no", "yes") {
    points = points + 1;
  }
  io.println("Quiz complete!");
  return 0;
}
